templateJson:
{
  "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
  "contentVersion": "1.0.0.0",
  "metadata": {
    "_generator": {
      "name": "bicep",
      "version": "0.45.6.27763",
      "templateHash": "9475785805886651535"
    },
    "description": "Azure-native NaC BFF baseline for a resource-group deployment in Germany West Central."
  },
  "parameters": {
    "location": {
      "type": "string",
      "defaultValue": "germanywestcentral",
      "allowedValues": [
        "germanywestcentral"
      ],
      "metadata": {
        "description": "Azure region for every regional resource. The baseline is intentionally pinned to Germany West Central."
      }
    },
    "environmentName": {
      "type": "string",
      "defaultValue": "test",
      "allowedValues": [
        "dev",
        "test",
        "prod"
      ],
      "metadata": {
        "description": "Short deployment environment identifier used in resource names and tags."
      }
    },
    "m365TenantId": {
      "type": "string",
      "minLength": 36,
      "maxLength": 36,
      "metadata": {
        "description": "Microsoft Entra tenant ID used for inbound token validation and Microsoft Graph token acquisition."
      }
    },
    "bffApiAudience": {
      "type": "string",
      "minLength": 7,
      "maxLength": 256,
      "metadata": {
        "description": "Exact Microsoft Entra audience expected in access tokens issued for the NaC BFF API."
      }
    },
    "bffRequiredDelegatedScope": {
      "type": "string",
      "allowedValues": [
        "Matter.Read"
      ],
      "metadata": {
        "description": "Single delegated scope required on inbound BFF access tokens for this synthetic MVP."
      }
    },
    "functionAppName": {
      "type": "string",
      "defaultValue": "func-nac-bff-test-funktion8",
      "allowedValues": [
        "func-nac-bff-test-funktion8"
      ],
      "metadata": {
        "description": "Globally unique fixed Azure Function hostname for the approved synthetic MVP."
      }
    },
    "maximumInstanceCount": {
      "type": "int",
      "defaultValue": 4,
      "minValue": 1,
      "maxValue": 10,
      "metadata": {
        "description": "Maximum Flex Consumption instances. The upper bound is a cost-control guardrail."
      }
    },
    "httpPerInstanceConcurrency": {
      "type": "int",
      "defaultValue": 16,
      "minValue": 1,
      "maxValue": 32,
      "metadata": {
        "description": "Maximum simultaneous HTTP trigger invocations per Flex Consumption instance."
      }
    },
    "tags": {
      "type": "object",
      "defaultValue": {},
      "metadata": {
        "description": "Additional non-sensitive resource tags. Baseline ownership tags cannot be overridden."
      }
    }
  },
  "variables": {
    "resourceToken": "[toLower(uniqueString(subscription().id, resourceGroup().id, parameters('environmentName')))]",
    "deploymentContainerName": "function-releases",
    "corsAllowedOrigins": [
      "https://funktion8.sharepoint.com",
      "https://teams.microsoft.com",
      "https://teams.cloud.microsoft"
    ],
    "resourceTags": "[union(parameters('tags'), createObject('workload', 'nac-bff', 'environment', parameters('environmentName'), 'managedBy', 'bicep', 'dataClassification', 'no-production-data'))]",
    "storageBlobDataOwnerRoleId": "b7e6dc6d-f1e8-4753-8033-0f276bb0955b",
    "monitoringMetricsPublisherRoleId": "3913510d-42f4-4e42-8a64-420c390055eb"
  },
  "resources": [
    {
      "type": "Microsoft.ManagedIdentity/userAssignedIdentities",
      "apiVersion": "2023-01-31",
      "name": "[format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]"
    },
    {
      "type": "Microsoft.Storage/storageAccounts",
      "apiVersion": "2023-05-01",
      "name": "[format('stnacbff{0}', variables('resourceToken'))]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "kind": "StorageV2",
      "sku": {
        "name": "Standard_LRS"
      },
      "properties": {
        "accessTier": "Hot",
        "allowBlobPublicAccess": false,
        "allowCrossTenantReplication": false,
        "allowSharedKeyAccess": false,
        "defaultToOAuthAuthentication": true,
        "minimumTlsVersion": "TLS1_2",
        "publicNetworkAccess": "Enabled",
        "supportsHttpsTrafficOnly": true,
        "networkAcls": {
          "bypass": "None",
          "defaultAction": "Allow",
          "ipRules": [],
          "virtualNetworkRules": []
        }
      }
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}', format('stnacbff{0}', variables('resourceToken')), 'default')]",
      "properties": {
        "deleteRetentionPolicy": {
          "enabled": false
        }
      },
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken')))]"
      ]
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices/containers",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}/{2}', format('stnacbff{0}', variables('resourceToken')), 'default', variables('deploymentContainerName'))]",
      "properties": {
        "publicAccess": "None"
      },
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices', format('stnacbff{0}', variables('resourceToken')), 'default')]"
      ]
    },
    {
      "type": "Microsoft.OperationalInsights/workspaces",
      "apiVersion": "2023-09-01",
      "name": "[format('log-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "properties": {
        "features": {
          "disableLocalAuth": true,
          "enableLogAccessUsingOnlyResourcePermissions": true,
          "immediatePurgeDataOn30Days": true
        },
        "publicNetworkAccessForIngestion": "Enabled",
        "publicNetworkAccessForQuery": "Enabled",
        "retentionInDays": 30,
        "sku": {
          "name": "PerGB2018"
        },
        "workspaceCapping": {
          "dailyQuotaGb": 1
        }
      }
    },
    {
      "type": "Microsoft.Insights/components",
      "apiVersion": "2020-02-02",
      "name": "[format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "kind": "web",
      "properties": {
        "Application_Type": "web",
        "DisableLocalAuth": true,
        "IngestionMode": "LogAnalytics",
        "RetentionInDays": 30,
        "WorkspaceResourceId": "[resourceId('Microsoft.OperationalInsights/workspaces', format('log-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "publicNetworkAccessForIngestion": "Enabled",
        "publicNetworkAccessForQuery": "Enabled"
      },
      "dependsOn": [
        "[resourceId('Microsoft.OperationalInsights/workspaces', format('log-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]"
      ]
    },
    {
      "type": "Microsoft.Insights/components/CurrentBillingFeatures",
      "apiVersion": "2015-05-01",
      "name": "[format('{0}/{1}', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')), 'Basic')]",
      "location": "[parameters('location')]",
      "properties": {
        "CurrentBillingFeatures": [
          "Basic"
        ],
        "DataVolumeCap": {
          "Cap": "[json('0.1')]",
          "StopSendNotificationWhenHitCap": false
        }
      },
      "dependsOn": [
        "[resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]"
      ]
    },
    {
      "type": "Microsoft.Web/serverfarms",
      "apiVersion": "2024-04-01",
      "name": "[format('plan-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "kind": "functionapp",
      "sku": {
        "name": "FC1",
        "tier": "FlexConsumption"
      },
      "properties": {
        "reserved": true,
        "zoneRedundant": false
      }
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "scope": "[resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken')))]",
      "name": "[guid(resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken'))), resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), variables('storageBlobDataOwnerRoleId'))]",
      "properties": {
        "principalId": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').principalId]",
        "principalType": "ServicePrincipal",
        "roleDefinitionId": "[subscriptionResourceId('Microsoft.Authorization/roleDefinitions', variables('storageBlobDataOwnerRoleId'))]"
      },
      "dependsOn": [
        "[resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "[resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken')))]"
      ]
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "scope": "[resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
      "name": "[guid(resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), variables('monitoringMetricsPublisherRoleId'))]",
      "properties": {
        "principalId": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').principalId]",
        "principalType": "ServicePrincipal",
        "roleDefinitionId": "[subscriptionResourceId('Microsoft.Authorization/roleDefinitions', variables('monitoringMetricsPublisherRoleId'))]"
      },
      "dependsOn": [
        "[resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "[resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]"
      ]
    },
    {
      "type": "Microsoft.Web/sites",
      "apiVersion": "2024-04-01",
      "name": "[parameters('functionAppName')]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "kind": "functionapp,linux",
      "identity": {
        "type": "UserAssigned",
        "userAssignedIdentities": {
          "[format('{0}', resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))))]": {}
        }
      },
      "properties": {
        "clientAffinityEnabled": false,
        "httpsOnly": true,
        "publicNetworkAccess": "Enabled",
        "serverFarmId": "[resourceId('Microsoft.Web/serverfarms', format('plan-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "siteConfig": {
          "alwaysOn": false,
          "cors": {
            "allowedOrigins": "[variables('corsAllowedOrigins')]",
            "supportCredentials": false
          },
          "ftpsState": "Disabled",
          "healthCheckPath": "/healthz",
          "http20Enabled": true,
          "minTlsVersion": "1.2",
          "remoteDebuggingEnabled": false
        },
        "functionAppConfig": {
          "deployment": {
            "storage": {
              "authentication": {
                "type": "UserAssignedIdentity",
                "userAssignedIdentityResourceId": "[resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]"
              },
              "type": "blobContainer",
              "value": "[format('{0}{1}', reference(resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken'))), '2023-05-01').primaryEndpoints.blob, variables('deploymentContainerName'))]"
            }
          },
          "runtime": {
            "name": "python",
            "version": "3.12"
          },
          "scaleAndConcurrency": {
            "instanceMemoryMB": 2048,
            "maximumInstanceCount": "[parameters('maximumInstanceCount')]",
            "triggers": {
              "http": {
                "perInstanceConcurrency": "[parameters('httpPerInstanceConcurrency')]"
              }
            }
          }
        }
      },
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices/containers', format('stnacbff{0}', variables('resourceToken')), 'default', variables('deploymentContainerName'))]",
        "[resourceId('Microsoft.Web/serverfarms', format('plan-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "[resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "[extensionResourceId(resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), 'Microsoft.Authorization/roleAssignments', guid(resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), variables('monitoringMetricsPublisherRoleId')))]",
        "[resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken')))]",
        "[extensionResourceId(resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken'))), 'Microsoft.Authorization/roleAssignments', guid(resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken'))), resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), variables('storageBlobDataOwnerRoleId')))]"
      ]
    },
    {
      "type": "Microsoft.Web/sites/config",
      "apiVersion": "2024-04-01",
      "name": "[format('{0}/{1}', parameters('functionAppName'), 'appsettings')]",
      "properties": {
        "APPLICATIONINSIGHTS_AUTHENTICATION_STRING": "[format('ClientId={0};Authorization=AAD', reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').clientId)]",
        "APPLICATIONINSIGHTS_CONNECTION_STRING": "[reference(resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2020-02-02').ConnectionString]",
        "AzureWebJobsStorage__accountName": "[format('stnacbff{0}', variables('resourceToken'))]",
        "AzureWebJobsStorage__clientId": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').clientId]",
        "AzureWebJobsStorage__credential": "managedidentity",
        "FUNCTIONS_WORKER_RUNTIME": "python",
        "M365_TENANT_ID": "[parameters('m365TenantId')]",
        "NAC_BFF_TENANT_ID": "[parameters('m365TenantId')]",
        "NAC_BFF_AUDIENCE": "[parameters('bffApiAudience')]",
        "NAC_BFF_REQUIRED_SCOPE": "[parameters('bffRequiredDelegatedScope')]",
        "M365_RUNTIME_CLIENT_ID": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').clientId]",
        "AZURE_CLIENT_ID": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').clientId]"
      },
      "dependsOn": [
        "[resourceId('Microsoft.Insights/components', format('appi-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "[resourceId('Microsoft.Web/sites', parameters('functionAppName'))]",
        "[resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]",
        "[resourceId('Microsoft.Storage/storageAccounts', format('stnacbff{0}', variables('resourceToken')))]"
      ]
    }
  ],
  "outputs": {
    "functionAppResourceId": {
      "type": "string",
      "value": "[resourceId('Microsoft.Web/sites', parameters('functionAppName'))]"
    },
    "functionAppHostName": {
      "type": "string",
      "value": "[reference(resourceId('Microsoft.Web/sites', parameters('functionAppName')), '2024-04-01').defaultHostName]"
    },
    "managedIdentityResourceId": {
      "type": "string",
      "value": "[resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken')))]"
    },
    "managedIdentityClientId": {
      "type": "string",
      "value": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').clientId]"
    },
    "managedIdentityPrincipalId": {
      "type": "string",
      "value": "[reference(resourceId('Microsoft.ManagedIdentity/userAssignedIdentities', format('id-nac-bff-{0}-{1}', parameters('environmentName'), variables('resourceToken'))), '2023-01-31').principalId]"
    }
  }
}
